def overall(frac, speedup, copy_frac=0.0):
    return 1 / ((1 - frac) + frac / speedup + copy_frac)

for frac in (0.3, 0.6, 0.9):
    print(f"scan·filter 비중 {int(frac*100)}%  가속 4.7배 -> 전체 {overall(frac, 4.7):.2f}배"
          f"  | 되돌림 5% 더하면 {overall(frac, 4.7, 0.05):.2f}배")
print("비중 60%면 무한히 빨라도 상한", round(1 / 0.4, 2), "배")

# scan·filter 비중 30%  가속 4.7배 -> 전체 1.31배  | 되돌림 5% 더하면 1.23배
# scan·filter 비중 60%  가속 4.7배 -> 전체 1.90배  | 되돌림 5% 더하면 1.73배
# scan·filter 비중 90%  가속 4.7배 -> 전체 3.43배  | 되돌림 5% 더하면 2.93배
# 비중 60%면 무한히 빨라도 상한 2.5 배
